// Generated by AIArtEngine. dsh 审批应答插件（approval/request → 用户同意卡）。
//
// 契约：把每一条 approval/request 作为**一行标记 JSON**写到 stdout，然后轮询应用写下的
// 回答文件，把用户的决定翻译成 dsh 的结果词表。除「应用亲笔写了 allow-once」之外的
// **所有路径都失败即关闭**：标记送不出去、回答文件不来、载荷读坏、任何抛错 → 'unavailable'
// （工具调用失败），而不是放行。dsh 只认 allowed-once 一种放行，且一次性。
//
// 与 runner 同样的往返机制（stdout 标记 + 回答文件轮询），但重开一个插件文件：
// 审批应答器的失败即关闭逻辑要被单独调用与测试，混在 700 行的 runner 里既拿不到覆盖，
// 也容易在改 runner 时被顺手改坏。
//
// 本文件**只 import node 内置模块**（无 dsh 依赖），因此测试可以把它当普通模块导入，
// 用假的 deps 驱动真实实现，直接断言「任何非 allow-once 的输入都不会变成放行」。
import { randomUUID } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

// 与 src/shared/dshApproval.ts 的 APPROVAL_MARKER 必须逐字一致（两侧由测试钉住）
const APPROVAL_BEGIN = '===BEGIN_APPROVAL==='
/** 等待用户决定的时限：超时按「没有审批通道」处理（工具调用失败），绝不默认放行 */
const APPROVAL_TIMEOUT_MS = 5 * 60 * 1000
const APPROVAL_POLL_MS = 250

/**
 * 读应用写下的回答文件内容，判定这次审批的结果。
 *
 * - 文件还没写完（JSON 半个）→ `pending`，继续等：应用是整体写盘，读到半截只说明时机太早；
 * - 明确写着 `decision: 'allow-once'` → 放行（唯一放行路径）；
 * - 明确写着 `decision: 'reject'` → 拒绝；
 * - 读得动但内容不认识（别的键、别的值、数组、null…）→ `unavailable`：
 *   宁可让工具调用失败，也不能把看不懂的东西当成授权。
 */
export function resolveApprovalAnswer(raw) {
  let parsed
  try {
    parsed = JSON.parse(raw)
  } catch {
    return { state: 'pending' }
  }
  if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
    if (parsed.decision === 'allow-once') return { state: 'decided', outcome: 'allowed-once' }
    if (parsed.decision === 'reject') return { state: 'decided', outcome: 'rejected' }
  }
  return { state: 'decided', outcome: 'unavailable' }
}

/** 标记行载荷：只带界面要展示的字段 + 回答文件路径（原因文案原样透传，应用侧不改写） */
export function approvalMarkerPayload(request, requestId, answerFile) {
  const callId = request?.callId
  const reason = request?.reason
  const displayReason = request?.displayReason
  return {
    requestId,
    toolName: typeof request?.toolName === 'string' && request.toolName ? request.toolName : 'tool',
    ...(typeof callId === 'string' && callId ? { callId } : {}),
    ...(typeof reason === 'string' && reason ? { reason } : {}),
    ...(typeof displayReason === 'string' && displayReason ? { displayReason } : {}),
    answerFile
  }
}

/**
 * 一条审批请求的完整应答流程。
 *
 * deps 由调用方注入（now / sleep / readAnswer / writeMarker / log），测试据此用假时钟
 * 与假文件系统驱动**同一份实现**，不需要真的等 5 分钟。
 */
export async function answerApproval(request, requestId, answerFile, deps) {
  if (request?.signal?.aborted) return 'cancelled'
  try {
    deps.writeMarker(
      '\n' +
        APPROVAL_BEGIN +
        JSON.stringify(approvalMarkerPayload(request, requestId, answerFile)) +
        '\n'
    )
  } catch (error) {
    // 连问题都送不到用户面前 = 没有审批通道。绝不能因为「说不出口」就默认同意。
    deps.log('[aiart-approval] marker delivery failed: ' + describe(error) + '\n')
    return 'unavailable'
  }
  const deadline = deps.now() + APPROVAL_TIMEOUT_MS
  try {
    while (deps.now() < deadline) {
      // 用户中止 / 本轮结束：dsh 已按取消处理，这里停止等待
      if (request?.signal?.aborted) return 'cancelled'
      const decision = resolveApprovalAnswer(deps.readAnswer(answerFile))
      if (decision.state === 'decided') return decision.outcome
      await deps.sleep(APPROVAL_POLL_MS)
    }
  } catch (error) {
    deps.log('[aiart-approval] answerer error: ' + describe(error) + '\n')
    return 'unavailable'
  }
  // 等满时限仍未拿到决定：按不可用收敛，工具调用失败并让模型看到真实原因
  deps.log('[aiart-approval] no decision within timeout; failing closed\n')
  return 'unavailable'
}

function describe(error) {
  return error instanceof Error ? error.message : String(error)
}

/** 真实运行环境下的依赖：stdout 给应用看，stderr 给开发者看 */
function defaultDeps() {
  return {
    now: () => Date.now(),
    sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    readAnswer: (file) => {
      try {
        return readFileSync(file, 'utf8')
      } catch {
        // 文件还没写：当成「还没有决定」，继续等
        return ''
      }
    },
    writeMarker: (line) => {
      process.stdout.write(line)
    },
    log: (text) => {
      process.stderr.write(text)
    }
  }
}

export const name = 'aiart-approval-answerer'

export function apply(ctx) {
  ctx.on('approval/request', (request) => {
    const runId = process.env.AIART_RUN_ID || 'run'
    const requestId = 'approval:' + runId + ':' + randomUUID()
    const answerFile = join(
      process.env.AIART_ASK_DIR || '',
      'aiart-approval-' + requestId.replace(/[^a-zA-Z0-9_-]/g, '-') + '.json'
    )
    // 兜底 catch 与 answerApproval 内部的 try 是两层：这里保证**任何**逃逸出来的
    // 异常（包括 deps 自身抛错）都收敛到 unavailable，而不是让 waterfall 抛错
    // （dsh 会把 answerer 抛错也归一成 unavailable，但显式返回更不易被改坏）。
    return answerApproval(request, requestId, answerFile, defaultDeps()).catch(() => 'unavailable')
  })
}
